import Foundation
import MLX
import Testing

@testable import MLXDINOv3

/// Every test hangs off this suite so that they run one at a time: MLX evaluation is not
/// safe to run from several tests at once.
@Suite("MLXDINOv3", .serialized)
struct AllTests {}

/// Files under `Fixtures`, generated by `Scripts/make_test_fixtures.py`.
enum Fixtures {
    // Built from the absolute path: on some macOS versions `resourceURL` is relative to the
    // bundle, and MLX's `loadArrays` does not resolve relative URLs.
    static let root = URL(fileURLWithPath: Bundle.module.resourcePath!)
        .appendingPathComponent("Fixtures")

    static func model(_ name: String) -> URL {
        root.appendingPathComponent("models/\(name)")
    }

    static func image(_ name: String) -> URL {
        root.appendingPathComponent("images/\(name)")
    }

    /// What Pillow produced for the fixture images, as `uint8` arrays.
    static func expectedPixels() throws -> [String: MLXArray] {
        try loadArrays(url: image("expected.safetensors"))
    }
}

/// A scratch directory that is removed when the value goes away.
final class TemporaryDirectory {
    let url: URL

    init() throws {
        url = FileManager.default.temporaryDirectory
            .appendingPathComponent("MLXDINOv3Tests-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
    }

    deinit {
        try? FileManager.default.removeItem(at: url)
    }

    /// Writes a model directory from in-memory weights and a config.
    func writeModel(weights: [String: MLXArray], config: Data) throws {
        try save(arrays: weights, url: url.appendingPathComponent("model.safetensors"))
        try config.write(to: url.appendingPathComponent("config.json"))
    }
}

/// Relative L2 distance between two arrays of the same shape.
func relativeError(_ a: MLXArray, _ b: MLXArray) -> Float {
    let x = a.asType(.float32).reshaped(-1)
    let y = b.asType(.float32).reshaped(-1)
    return (sqrt(((x - y) * (x - y)).sum()) / sqrt((y * y).sum())).item(Float.self)
}

func expectClose(
    _ actual: MLXArray, _ expected: MLXArray, tolerance: Float = 1e-4,
    _ label: String = "", sourceLocation: SourceLocation = #_sourceLocation
) {
    guard actual.shape == expected.shape else {
        Issue.record(
            "\(label) shape \(actual.shape) != \(expected.shape)", sourceLocation: sourceLocation)
        return
    }
    let error = relativeError(actual, expected)
    #expect(
        error <= tolerance, "\(label) relative error \(error) > \(tolerance)",
        sourceLocation: sourceLocation)
}

/// Largest difference, in 8-bit levels, between two pixel arrays.
func maxPixelDifference(_ actual: MLXArray, _ expected: MLXArray) -> Int32 {
    guard actual.shape == expected.shape else { return .max }
    return abs(actual.asType(.int32) - expected.asType(.int32)).max().item(Int32.self)
}
